head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf94000";

// [A] 초기 목록 미해결 — jldinf94000: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf94000.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_go_onclick
 * @description btn_go 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_go_onclick = function(e){
    try {
        scwin.go()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf94000.btn_go_onclick' }); }
};

/**
 * @method
 * @name btn_go_onfocus
 * @description btn_go 포커스 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_go_onfocus = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.blur()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf94000.btn_go_onfocus' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name go
 * @description go 처리
 * @returns {void}
 * @hidden N
 */
scwin.go = function () {
    const sHost = location.hostname;
    if ($c.util.getComponent('ipt_stdCdGrntFeeApplYn').getValue() === 'Y') {
        $c.win.closePopup();
    } else {
        history.go(-1);
    }
};
